-- reports/crash-by-source-url
-- The live crash a news link is already attached to, if any (the same link never makes a second live crash).
-- Rejected crashes are ignored: otherwise one rejected report would block its link for everyone (audit finding 3).
--
-- Parameters, with the example values used to render this file:
--   $1 = "example.com/news/1"
--   $2 = "rejected"
--   $3 = 1
--
-- Generated by `pnpm db:queries` from lib/db/queries/reports.ts. Do not edit by hand.

select "crash_sources"."crash_id", "sources"."id"
from "sources"
inner join "crash_sources" on "crash_sources"."source_id" = "sources"."id"
inner join "crashes" on "crashes"."id" = "crash_sources"."crash_id"
where ("sources"."normalized_url" = $1
  and "crashes"."status" <> $2)
limit $3;
